import subprocess
import shlex
from datetime import datetime

def task_func(script_path: str) -> dict:
    start_time = datetime.now()

    try:
        result = subprocess.run(
            [script_path],
            capture_output=True,
            text=True,
            timeout=300  # 5 minute timeout, adjust as needed
        )
        stdout = result.stdout
        stderr = result.stderr
        exit_code = result.returncode

        if exit_code != 0:
            raise subprocess.CalledProcessError(exit_code, script_path, result.stdout, result.stderr)

    except subprocess.TimeoutExpired:
        end_time = datetime.now()
        return {
            "start_time": start_time.isoformat(),
            "end_time": end_time.isoformat(),
            "stdout": "",
            "stderr": "Script execution timed out"
        }
    except subprocess.CalledProcessError as e:
        end_time = datetime.now()
        return {
            "start_time": start_time.isoformat(),
            "end_time": end_time.isoformat(),
            "stdout": e.stdout or "",
            "stderr": e.stderr or f"Script failed with exit code {e.returncode}"
        }
    except Exception as e:
        end_time = datetime.now()
        return {
            "start_time": start_time.isoformat(),
            "end_time": end_time.isoformat(),
            "stdout": "",
            "stderr": str(e)
        }

    end_time = datetime.now()

    return {
        "start_time": start_time.isoformat(),
        "end_time": end_time.isoformat(),
        "stdout": stdout,
        "stderr": stderr
